`);constructor(){_y(()=>this.observeSections());}sections=[{id:"getting-started",title:"Getting started",description:"Install styles, register app-wide defaults, then open your first modal.",examples:[{id:"setup",kind:"docs",label:"Setup",description:"Global styles and provideModalieur() in app.config.ts.",btnClass:"btn-secondary",code:`// angular.json \u2192 styles
